import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import * as Diff from 'diff';
import './DiffChecker.css';

const DiffChecker = () => {
  const [originalText, setOriginalText] = useState('');
  const [changedText, setChangedText] = useState('');
  const [showDiff, setShowDiff] = useState(false);
  const [diffResults, setDiffResults] = useState({ original: [], changed: [] });

  const findDifference = () => {
    const originalLines = originalText.split('\n');
    const changedLines = changedText.split('\n');
    const lineDiff = Diff.diffLines(originalText, changedText);

    const originalResult = [];
    const changedResult = [];

    let originalIndex = 0;
    let changedIndex = 0;

    lineDiff.forEach((part) => {
      const lines = part.value.split('\n').filter((line, idx, arr) => {
        return idx < arr.length - 1 || line !== '';
      });

      if (part.added) {
        // Lines added in changed text
        lines.forEach((line) => {
          changedResult.push({ 
            text: line, 
            type: 'added',
            parts: [{ value: line, added: true }]
          });
          changedIndex++;
        });
      } else if (part.removed) {
        // Lines removed from original text
        lines.forEach((line) => {
          originalResult.push({ 
            text: line, 
            type: 'removed',
            parts: [{ value: line, removed: true }]
          });
          originalIndex++;
        });
      } else {
        // Unchanged lines - check if next part is a modification
        lines.forEach((line, idx) => {
          originalResult.push({ 
            text: line, 
            type: 'unchanged',
            parts: [{ value: line }]
          });
          changedResult.push({ 
            text: line, 
            type: 'unchanged',
            parts: [{ value: line }]
          });
          originalIndex++;
          changedIndex++;
        });
      }
    });

    // Now do character-level diff for modified lines
    const processedOriginal = [];
    const processedChanged = [];

    let origIdx = 0;
    let chgIdx = 0;

    while (origIdx < originalResult.length || chgIdx < changedResult.length) {
      const origLine = originalResult[origIdx];
      const chgLine = changedResult[chgIdx];

      // If both lines exist and one is removed and one is added, they might be modifications
      if (origLine && chgLine && origLine.type === 'removed' && chgLine.type === 'added') {
        // Do character-level diff
        const charDiff = Diff.diffChars(origLine.text, chgLine.text);

        processedOriginal.push({
          text: origLine.text,
          type: 'modified',
          parts: charDiff.filter(p => !p.added)
        });

        processedChanged.push({
          text: chgLine.text,
          type: 'modified',
          parts: charDiff.filter(p => !p.removed)
        });

        origIdx++;
        chgIdx++;
      } else if (origLine && origLine.type === 'removed') {
        processedOriginal.push(origLine);
        origIdx++;
      } else if (chgLine && chgLine.type === 'added') {
        processedChanged.push(chgLine);
        chgIdx++;
      } else {
        if (origLine) {
          processedOriginal.push(origLine);
          origIdx++;
        }
        if (chgLine) {
          processedChanged.push(chgLine);
          chgIdx++;
        }
      }
    }

    setDiffResults({ original: processedOriginal, changed: processedChanged });
    setShowDiff(true);
  };

  const clearAll = () => {
    setOriginalText('');
    setChangedText('');
    setShowDiff(false);
    setDiffResults({ original: [], changed: [] });
  };

  const renderDiffLine = (line, index) => {
    const baseClassName = `diff-line ${line.type}`;

    return (
      <div key={index} className={baseClassName}>
        <span className="line-number">{index + 1}</span>
        <span className="line-content">
          {line.parts && line.parts.length > 0 ? (
            line.parts.map((part, partIndex) => {
              if (part.added) {
                return (
                  <span key={partIndex} className="char-added">
                    {part.value}
                  </span>
                );
              } else if (part.removed) {
                return (
                  <span key={partIndex} className="char-removed">
                    {part.value}
                  </span>
                );
              } else {
                return <span key={partIndex}>{part.value}</span>;
              }
            })
          ) : (
            line.text || '\u00A0'
          )}
        </span>
      </div>
    );
  };

  return (
    <div className="diff-checker-page">
      <div className="diff-header">
        <Link to="/" className="back-button">← Back to Home</Link>
        <h1>Diff Checker</h1>
        <p>Compare and find differences between two texts</p>
      </div>

      <div className="diff-container">
        {!showDiff ? (
          <div className="input-section">
            <div className="text-input-container">
              <div className="text-input-box">
                <h3>Original Text</h3>
                <textarea
                  value={originalText}
                  onChange={(e) => setOriginalText(e.target.value)}
                  placeholder="Paste your original text here..."
                  className="text-area"
                />
              </div>
              <div className="text-input-box">
                <h3>Changed Text</h3>
                <textarea
                  value={changedText}
                  onChange={(e) => setChangedText(e.target.value)}
                  placeholder="Paste your changed text here..."
                  className="text-area"
                />
              </div>
            </div>
            <div className="button-group">
              <button onClick={findDifference} className="find-diff-button">
                Find Difference
              </button>
              <button onClick={clearAll} className="clear-button">
                Clear All
              </button>
            </div>
          </div>
        ) : (
          <div className="results-section">
            <div className="results-header">
              <h2>Comparison Results</h2>
              <button onClick={() => setShowDiff(false)} className="edit-button">
                ← Edit Texts
              </button>
            </div>
            <div className="legend">
              <span className="legend-item">
                <span className="legend-color removed-color"></span>
                Deletions
              </span>
              <span className="legend-item">
                <span className="legend-color added-color"></span>
                Additions
              </span>
            </div>
            <div className="diff-results">
              <div className="diff-column">
                <h3>Original Text</h3>
                <div className="diff-content">
                  {diffResults.original.map((line, index) => renderDiffLine(line, index))}
                </div>
              </div>
              <div className="diff-column">
                <h3>Changed Text</h3>
                <div className="diff-content">
                  {diffResults.changed.map((line, index) => renderDiffLine(line, index))}
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default DiffChecker;
